 ;
 const updateOrder=async(id,v,providedReason=null)=>{
   let cancellationReason=providedReason;
   if(v==="cancelled"){
     if(cancellationReason===null||cancellationReason===undefined){const order=orders.find(o=>o.id===id);cancellationReason=prompt("Reason for cancelling order #"+(order?.order_number||id)+":","");if(cancellationReason===null)return}
     cancellationReason=String(cancellationReason).trim();
     if(!cancellationReason){setMessage("Please enter a reason for cancelling the order.");return}
     if(!confirm("Cancel order #"+(orders.find(o=>o.id===id)?.order_number||id)+"?"))return;
   }
   if(v==="cancelled"){
     try{
       setNcmBusy(true);
       const{error}=await supabase.rpc("handle_order_cancellation",{p_order_id:id,p_action:"cancel",p_reason:cancellationReason,p_admin_note:cancellationReason});
       if(error)throw error;
       setNcmSyncMessage("Order cancelled, inventory restored, and the reason was shared with the customer.");
       await loadOrders();
     }catch(e){setMessage("Cancellation: "+(e?.message||"Unable to cancel order."))}finally{setNcmBusy(false)}
   }else{
     const{error}=await supabase.from("orders").update({order_status:v}).eq("id",id);
     if(error)setMessage(error.message);else{setNcmSyncMessage("");loadOrders()}
   }
 };
 const reviewCancellation=async(o,action)=>{
   let note=null;
   if(action==="reject_cancellation"){note=prompt("Reason/note for rejecting the cancellation (optional):","");if(note===null)return}
   if(!confirm(action==="accept_cancellation"?"Accept this cancellation request?":"Reject this cancellation request?"))return;
   try{
     setNcmBusy(true);
     const{data,error}=await supabase.rpc("handle_order_cancellation",{p_order_id:o.id,p_action:action,p_reason:null,p_admin_note:note||null});
     if(error)throw error;
     setNcmSyncMessage(action==="accept_cancellation"?"Cancellation accepted and order cancelled.":"Cancellation request rejected.");
     loadOrders();
   }catch(e){setMessage("Cancellation: "+(e?.message||"Unable to review request."))}
   finally{setNcmBusy(false)}
 };
